mapper.select:
SELECT id, tenant_id, psid, page_id,
       event_type, message_id, message_type, content, direction, send_time,
       crm_lead_id, crm_contact_id,
       status, processing_error, create_time, update_time
FROM crm_messenger_webhook_event
WHERE tenant_id = #{tenantId}
  AND message_id = #{messageId}
  AND event_type = #{eventType}
ORDER BY id DESC
LIMIT 1

SELECT id, tenant_id, psid, page_id,
       event_type, message_id, message_type, content, direction, send_time,
       crm_lead_id, crm_contact_id,
       status, processing_error, create_time, update_time
FROM crm_messenger_webhook_event
WHERE tenant_id = #{tenantId}

    AND psid = #{psid}


    AND status = #{status}


    AND event_type = #{eventType}


    AND page_id = #{pageId}


    AND send_time >= #{startTime}


    AND send_time <= #{endTime}

ORDER BY create_time DESC

SELECT COUNT(1)
FROM crm_messenger_webhook_event
WHERE tenant_id = #{tenantId}

    AND direction = #{direction}


    AND send_time >= #{startTime}


    AND send_time <= #{endTime}
